package com.vault.entity;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="activity_logs",indexes=@Index(name="idx_activity_owner_time",columnList="user_id,created_at")) public class ActivityLog{
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="api_key_id") private ApiKey apiKey;@Column(nullable=false,length=30) private String action;@Column(nullable=false,length=500) private String description;@Column(name="ip_address",length=48) private String ipAddress;@Column(name="created_at",nullable=false) private Instant createdAt=Instant.now();protected ActivityLog(){}public ActivityLog(User u,ApiKey k,String a,String d,String ip){user=u;apiKey=k;action=a;description=d;ipAddress=ip;}public UUID getId(){return id;}public String getAction(){return action;}public String getDescription(){return description;}public Instant getCreatedAt(){return createdAt;}}
